# ================================================================ part 7: asset turnover
opener(7, 'מחזור הנכסים', 'שאלת החלק: כמה מכירות מפיק כל שקל שהושקע בנכסים?',
       ['דוגמה: סופרמרקט ומלון, אותן מכירות', 'הכלל: מחזור נכסים ומחזור רכוש קבוע', 'מסבירים יחד', 'נחשו: מחזור נכסים לפי ענף', 'מכונה ישנה: מלכודת של ערכים בספרים'], 15, note=CYCMAP(4))

_two = lambda title, rows: f'<div class="col"><div class="card at2"><b class="ct">{TX(title)}</b>' + ONE(rows, 'as') + '</div></div>'
S('e-at', 'דוגמה', 'סופרמרקט ומלון: אותן מכירות, נכסים שונים מאוד',
  '<div class="row eq2 top">'
  + _two('הסופרמרקט', [(1, 'מכירות בשנה', '10,000', 'מאיפה המספר', ['מדוח רווח והפסד: 10,000 אלפי ש״ח.'], 'הסרט.'),
                       (2, 'נכסים, ממוצע', '4,000', 'מאיפה המספר', ['מהמאזנים: מדפים, מקררים, מלאי וקופות. הממוצע של תחילת השנה וסופה.'], 'התמונה.'),
                       (3, 'מחזור נכסים', '2.5', 'איך חישבנו', ['10,000 חלקי 4,000: 2.5.'], 'כל שקל של נכסים מפיק 2.5 ש״ח של מכירות בשנה.')])
  + _two('המלון', [(4, 'מכירות בשנה', '10,000', 'מאיפה המספר', ['מדוח רווח והפסד: 10,000 אלפי ש״ח.'], 'אותן מכירות בדיוק.'),
                   (5, 'נכסים, ממוצע', '25,000', 'מאיפה המספר', ['מהמאזנים: בניין ליד הים, חדרים, בריכה ומטבח.'], 'התמונה: גדולה פי 6.25.'),
                   (6, 'מחזור נכסים', '0.4', 'איך חישבנו', ['10,000 חלקי 25,000: 0.4.'], 'כל שקל של נכסים מפיק 40 אגורות של מכירות בשנה.')])
  + '</div>' + BAND('dg', 'המלון אינו ״גרוע״ מהסופרמרקט: בניין ליד הים עולה הרבה, ומשרת שנים רבות. לכן משווים מחזור נכסים רק בתוך אותו ענף, ולאורך זמן.', 7), kick='חלק 7 · דוגמה')

S('r-at', 'הכלל', 'מהדוגמה לכלל: מחזור נכסים ומחזור רכוש קבוע',
  DEF('רכוש קבוע (Property, plant and equipment)', 'נכסים מוחשיים שהחברה משתמשת בהם לאורך שנים: מבנים, מכונות, ציוד. ״נטו״: העלות, פחות הפחת שנצבר.',
      'מכונה שנקנתה ב-1,000 אלפי ש״ח, ושנצבר עליה פחת של 300: רכוש קבוע נטו של 700.', n=1, trm='ppe')
  + '<div class="row eq2 top">' + RDEF(2, 'מחזור נכסים', 'Asset turnover', 'מכירות', 'סך נכסים ממוצע', 'atr')
  + RDEF(3, 'מחזור רכוש קבוע', 'Fixed asset turnover', 'מכירות', 'רכוש קבוע נטו ממוצע', 'fatr') + '</div>'
  + BAND('note', 'בשני היחסים, ערך גבוה יותר: הנכסים מנוצלים טוב יותר להפקת הכנסות. כאן אין ״ימים״: היחס עצמו הוא התשובה, בשקלים של מכירות לכל שקל של נכסים.', 4), kick='חלק 7 · הכלל')

