# ================================================================ part 8: a full efficiency analysis
opener(8, 'ניתוח יעילות מלא', 'שאלת החלק: תעשיות נירוסטה התרחבה. האם היא גם נעשתה יעילה יותר?',
       ['מסבירים יחד: המחזור של נירוסטה, 2025 מול 2026', 'הנכסים, והקשר לנזילות', 'שלוש שאלות על הטבלה, מהקלה לקשה', 'מהמספרים למסקנה', 'מה היחסים אינם רואים', 'ארגז הכלים, ומה למדנו'], 30, note=CYCMAP(5))

_FL = {'A1': 'תעשיות נירוסטה, אלפי ש״ח', 'B1': 'שנת 2026', 'C1': 'שנת 2025', 'D1': 'ענף', 'A2': 'מכירות', 'A3': 'עלות המכר', 'A4': 'קניות', 'A5': 'מלאי ממוצע', 'A6': 'לקוחות ממוצע', 'A7': 'ספקים ממוצע',
       'A8': 'ימי מלאי', 'A9': 'ימי לקוחות', 'A10': 'ימי ספקים', 'A11': 'מחזור המרת המזומן'}
_ff = lambda c: {f'{c}8': f'=365/({c}3/{c}5)', f'{c}9': f'=365/({c}2/{c}6)', f'{c}10': f'=365/({c}4/{c}7)', f'{c}11': f'={c}8+{c}9-{c}10'}
_FS = {**_ff('B'), **_ff('C')}
_fn = {8: 'ימי מלאי: 365 חלקי מחזור המלאי', 9: 'ימי לקוחות: 365 חלקי מחזור הלקוחות', 10: 'ימי ספקים: 365 חלקי מחזור הספקים', 11: 'מחזור המרת המזומן'}
