   qmc=RLIST([('מחזור נכסים', 'מכירות', 'סך נכסים ממוצע'), ('יחס שוטף', 'נכסים שוטפים', 'התחייבויות שוטפות'), ('יחס מזומן', 'מזומנים', 'התחייבויות שוטפות')])
